import{z as B,x as A,o,c as p,q as l,j as n,D as E,d as e,s as i,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"激活离群值为何出现","description":"","frontmatter":{"title":"激活离群值为何出现","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/why-activation-outliers.md","filePath":"llm/why-activation-outliers.md","lastUpdated":1791413859000}'),d={name:"llm/why-activation-outliers.md"};function m(h,a,D,u,C,f){const r=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=l('<h1 id="激活离群值为何出现" tabindex="-1">激活离群值为何出现 <a class="header-anchor" href="#激活离群值为何出现" aria-label="Permalink to &quot;激活离群值为何出现&quot;">​</a></h1><div class="epigraph"><p>少数通道的激活幅度比其余大上两个数量级时，按张量统计的量化器会为这几根钉子付出全部的格子，其余通道挤在零附近。</p><footer>—— 对照 SmoothQuant、LLM.int8() 对激活离群通道的观察；不是权重量化课的重复</footer></div><p><a href="/llm/draft-as-compression">上一课</a> 把投机草稿写成对下一步分布的有损压缩。本课转到<strong>同一张网内部</strong>为何难压：激活（以及部分权重行）出现离群通道，使按张量或按 token 的均匀量化失效。结构剪枝课已经能删宽、删层；它们不解释「为什么 8bit 激活在某几维炸」。后课量化与剪枝的分工默认你会：离群是统计现象，有结构来源，不是随机坏点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLM 的 FFN 与注意力输出里，常有极少数 hidden 维在很多 token 上同时取极大值。LLM.int8() 把它们当「新兴维度」单独留精度；SmoothQuant 把量化难度从激活挪到权重。现象先于方法：若激活近似高斯，INT8 格子够用；若第 \\(99.9\\) 百分位是均值的 \\(50\\) 倍，格子全被这根钉占用，其余维量化成零，质量崩在看似「只有 0.1% 异常」上。</p><p><span class="marginnote">数字实例：INT8 均匀量化在 \\([-s, s]\\) 里只铺 256 个格子。若一根钉子的幅度是其余通道的 50 倍，尺度 \\(s\\) 必须迁就它，其余通道只分到约 \\(256/50\\approx 5\\) 个格子的有效分辨率——0.1% 的异常点，偷走了 95% 以上的量化精度。</span></p><p>缺口是 <strong>为什么训练会长出钉子</strong>，而不是又一篇 INT8 配方。来源候选包括：RMSNorm / LayerNorm 的尺度、残差累积、词嵌入与 lm_head 的未归一化方向、RoPE 与长上下文、以及 MoE 共享通路上每个 token 都打到的通道。搞清来源，才能决定是平滑、旋转、剪掉该通道，还是承认它在承载功能不能动。</p><h3 id="离群不是噪声-常常是功能" tabindex="-1">离群不是噪声，常常是功能 <a class="header-anchor" href="#离群不是噪声-常常是功能" aria-label="Permalink to &quot;离群不是噪声，常常是功能&quot;">​</a></h3><p>若某通道在「句首 / 标点 / 特殊 token」上系统激活，它可能在当位置或分隔符探测器。剪掉或钳制会伤格式。若只在某几层、某几个专家上出现，可能是路由或残差的尺度事故，钳制更安全。诊断要看 <strong>哪些 token、哪些层、是否跨数据域稳定</strong>，不能只看一张激活直方图。<span class="marginnote">权重离群与激活离群相关但不等同。某权重行很大，会把对应激活推大；激活离群也可以来自输入方向碰巧对准一个并不算大的权重。SmoothQuant 的迁移假设「迁移后权重仍可量化」；若权重已经处于离群，迁移只是把钉子换边。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="测量、阈值与钳制消融" tabindex="-1">测量、阈值与钳制消融 <a class="header-anchor" href="#测量、阈值与钳制消融" aria-label="Permalink to &quot;测量、阈值与钳制消融&quot;">​</a></h3><p>测量：对校准集记录每层每通道的 \\(\\max |h|\\)、RMS、以及跨 token 的出现频率。离群通道定义为相对中位 RMS 超过阈值（如 \\(10\\times\\)）且在高比例 token 上复现。再做消融：将该通道在前向钳制到中位，看 CE 与下游。CE 几乎不变则更像尺度冗余；显著变差则像功能维。</p><p>与归一化：Pre-LN 残差流的尺度由各子层输出累加。若某子层不遵守「输出 \\(O(1)\\)」，钉子会沿深度放大。μP 与残差缩放课管训练期；已经训完的模型，钉子是既成事实。QAT 可以从小重建尺度，但贵。推理期平滑（逐通道缩放 \\(h\\leftarrow h/\\sigma,\\ W\\leftarrow W\\sigma\\)）不改变数学函数（在无限精度下），只改变哪一侧更好量化。</p>',13)),(o(),n(s,null,{default:E(()=>[i(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%9A%90%E8%97%8F%E6%80%81%E9%80%90%E9%80%9A%E9%81%93%E7%BB%9F%E8%AE%A1%22%5D%20--%3E%20DET%5B%22%E5%A4%8D%E7%8E%B0%E7%9A%84%E7%A6%BB%E7%BE%A4%E7%BB%B4%22%5D%0A%20%20DET%20--%3E%20ABL%5B%22%E9%92%B3%E5%88%B6%E6%B6%88%E8%9E%8D%22%5D%0A%20%20ABL%20--%3E%20FUN%7B%22%E4%BC%A4%E8%B4%A8%E9%87%8F%3F%22%7D%0A%20%20FUN%20--%3E%7C%E6%98%AF%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%EF%BC%9A%E5%B9%B3%E6%BB%91%E6%88%96%E9%AB%98%E7%B2%BE%E5%AD%A4%E5%B2%9B%22%5D%0A%20%20FUN%20--%3E%7C%E5%90%A6%7C%20PRN%5B%22%E5%8F%AF%E5%89%AA%E6%88%96%E9%92%B3%E5%88%B6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("一个有用的图像：残差流里少数方向承担「通配符计数器」或「注意力汇」——很多 query 都要读的全局位。训练没有稀疏惩罚时，把这种全局位塞进单通道比散到多通道更省参数，优化器会找到这个解。于是离群是 "),t("strong",null,"压缩功能到低维"),e(" 的副作用，与模型「太大」无关，小模型也会有，只是大模型上更刺眼因为你开始量化。")],-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：「注意力汇」像办公室门口的公告板——不管谁要找信息都先瞟它一眼。网络发现把这种「人人都要读的全局信号」集中塞进一个通道最省参数，于是这根通道越长越大。它大不是病，是功能；压它之前先想想谁在读它。")],-1)),a[6]||(a[6]=t("p",null,"长上下文与 RoPE：某些通道可能编码幅度极大的相位，外推失败时激活爆炸，离群变成长度相关。这与短校准集上看到的钉子集合不同。校准必须覆盖目标长度，否则 SmoothQuant 的 \\(\\sigma\\) 估错，线上长请求才炸。",-1)),(o(),n(s,null,{default:E(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E6%BF%80%E6%B4%BB%E6%9C%89%E9%92%89%E5%AD%90%2C%20%E6%9D%83%E9%87%8D%E5%B9%B3%E6%BB%91%22%5D%20--%3E%20SC%5B%22%E6%8C%89%E9%80%9A%E9%81%93%E5%8F%96%E7%BC%A9%E6%94%BE%20sigma%22%5D%0A%20%20SC%20--%3E%20H2%5B%22%E6%BF%80%E6%B4%BB%E7%BC%A9%E5%B0%8F%3A%20h%20%2F%20sigma%22%5D%0A%20%20SC%20--%3E%20W2%5B%22%E6%9D%83%E9%87%8D%E6%94%BE%E5%A4%A7%3A%20W%20*%20sigma%22%5D%0A%20%20H2%20--%3E%20Q1%5B%22%E6%BF%80%E6%B4%BB%E5%8F%98%E5%B9%B3%20%E2%86%92%20INT8%20%E6%A0%BC%E5%AD%90%E5%A4%9F%E7%94%A8%22%5D%0A%20%20W2%20--%3E%20Q2%7B%22%E6%9D%83%E9%87%8D%E5%90%83%E4%B8%8B%E9%9A%BE%E5%BA%A6%E5%90%8E%E4%BB%8D%E5%A5%BD%E9%87%8F%E5%8C%96%E5%90%97%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20GOOD%5B%22%E4%B8%A4%E4%BE%A7%E9%83%BD%E8%83%BD%E9%87%8F%E5%8C%96%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%9D%83%E9%87%8D%E6%9C%AC%E6%9D%A5%E4%B9%9F%E6%9C%89%E9%92%89%E5%AD%90%22%7C%20BAD%5B%22%E9%92%89%E5%AD%90%E5%8F%AA%E6%98%AF%E6%8D%A2%E8%BE%B9%2C%20%E6%80%BB%E8%AF%AF%E5%B7%AE%E4%B8%8D%E9%99%8D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">为什么 \\(h\\leftarrow h/\\sigma,\\ W\\leftarrow W\\sigma\\) 不改变输出：把 \\((h/\\sigma)\\cdot(W\\sigma)\\) 展开先除后乘正好消掉，无限精度下数学严格相等。它改变的只是「谁好量化」——把激活压平、难度转嫁给权重，这就是 SmoothQuant 名字的由来。</span></p><p><span class="marginnote">MoE <a href="/llm/moe-shared-routed-size">共享专家</a> 的离群会被每个 token 打到，量化误差变成全局的；路由专家的离群只打中被选 token，误差呈稀疏。共享通路更应保留精度或做逐通道平滑。配比 \\(\\rho\\) 大，问题更像稠密模型。</span></p><h3 id="与-layerdrop、剪枝的交叉" tabindex="-1">与 LayerDrop、剪枝的交叉 <a class="header-anchor" href="#与-layerdrop、剪枝的交叉" aria-label="Permalink to &quot;与 LayerDrop、剪枝的交叉&quot;">​</a></h3><p>若离群集中在即将被<a href="/llm/layer-prune">层剪</a>删掉的块里，先剪层再量化，钉子可能消失。若钉子在底层嵌入几何，剪中间层无济于事。顺序应是：测钉子位置 → 再决定剪深度还是平滑激活。随机先量化再抱怨 INT8 不行，是把诊断顺序走反。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>钳制训练（activation clipping）可减少钉子，但改变函数，需要续训。只在推理钳制而不续训，等于给网络加了一个校准集上拟合的非线性，域外 token 会把别的通道顶成新钉子。旋转 / 正交变换（如某些量化前处理把离群打散到多维）对「少数通道极大」有效，对「所有通道都有中等厚尾」无效。先看谱再选工具。</p><p>不要把视觉 token、音频码的动态范围和文本隐藏态混成一张表。多模态早融合里视觉前缀的离群统计可以完全不同，共用一组 SmoothQuant 系数会牺牲其中一模态。分模态、分层校准。</p><p><span class="marginnote">本课不给出「离群的第一条数学定理」。经验机制足够指导压缩顺序：测量、消融、再平滑或剪。把钉子神秘化成模型觉醒，对工程无帮助。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激活离群是少数高频、高幅度通道，破坏按张量量化的格子分配。</li><li>先测 token / 层 / 域上的复现，再消融判断功能维还是尺度事故。</li><li>来源常与残差尺度、全局位压缩、长上下文、共享专家有关。</li><li>平滑迁移钉子到权重侧；功能维应留精度而不是剪掉。</li><li>校准覆盖目标长度与模态；顺序是诊断再压缩。</li><li>出处：LLM.int8()、SmoothQuant 等对离群通道的实证；结合残差与 MoE 配比。</li></ul>',10))])}const g=B(d,[["render",m]]);export{F as __pageData,g as default};
